import { getAssetHostForServices, prod_urls } from 'config/api';

const getHostFromAssetBase = (assetBase: string): string | null => {
  try {
    return new URL(assetBase).host;
  } catch {
    return null;
  }
};

const PROD_ASSET_HOST = getHostFromAssetBase(prod_urls.assets);

const isProdAssetHost = (host: string): boolean =>
  Boolean(PROD_ASSET_HOST) && host === PROD_ASSET_HOST;

/**
 * Resolves production CDN asset URLs to the current environment before a
 * Markdown image is rendered.
 */
export const resolveMarkdownAssetUrl = (src: string): string => {
  if (!PROD_ASSET_HOST) return src;

  const currentAssetHost = getHostFromAssetBase(getAssetHostForServices());

  if (!currentAssetHost || isProdAssetHost(currentAssetHost)) return src;

  try {
    const parsed = new URL(src);

    if (!isProdAssetHost(parsed.host)) return src;

    const targetBase = new URL(getAssetHostForServices());
    parsed.protocol = targetBase.protocol;
    parsed.host = targetBase.host;

    return parsed.href;
  } catch {
    return src;
  }
};
